按 Enter 返回...&#34;) elif &#34;開啟專案&#34; in action: if sys.platform == &#39;darwin&#39;: os.system(&#34;open .&#34;) else: os.startfile(&#34;.&#34;) elif &#34;Git&#34; in action: run_task(&#34;Git Pull&#34;, &#34;git pull&#34;) run_task(&#34;Git Push&#34;, &#34;git push&#34;) input(&#34;
